using System;using Mirror;using UnityEngine;using ROM.UI.Sprint01;
namespace ROM.Progression {
public sealed partial class RiftJournalPlayer {
 [Command]public void CmdVendorRepair(string token,int sequence,string item,bool all,int expectedCost){bool ok=ServerVendorRepair(token,sequence,item,all,expectedCost,out var message);VendorReply(message);if(!ok)Report(message);}
 [Server]public bool ServerVendorRepair(string token,int sequence,string item,bool all,int expectedCost,out string message){message="Presupuesto vencido o ya procesado.";if(string.IsNullOrEmpty(token)||token!=vendorToken||sequence!=vendorSequence||Mirror.NetworkTime.time<vendorCommandAt)return false;message="Reparación disponible cerca del NPC en Host local, fuera de un intercambio.";if(!VendorAllowed(vendorNpc,out var npc)||!npc.Goods.Repairs||!Combat||!Combat.Prototype)return false;State.EnsureDurability();var quote=State.RepairQuote(item,all);if(quote==null){message="Ese equipo no te pertenece.";return false;}if(quote.Missing<=0){message="El equipo ya está completo. No se cobró oro.";return false;}if(quote.Cost!=expectedCost){message="El presupuesto cambió. Revisá el nuevo coste antes de confirmar.";return false;}int gold=RiftExplorationProgress.Gold;if(gold<quote.Cost){message="Oro común insuficiente para reparar.";return false;}var next=JsonUtility.FromJson<JournalState>(JsonUtility.ToJson(State));next.RestoreDurability(quote);try{RiftVendorPersistence.Commit(path,JsonUtility.ToJson(next),State.CharacterId,gold-quote.Cost,RiftVillageSupplies.Count(0),RiftVillageSupplies.Count(1));}catch(Exception e){Debug.LogWarning("Repair not committed: "+e.Message);message="No se pudo guardar la reparación.";return false;}State=next;vendorSequence++;vendorCommandAt=Mirror.NetworkTime.time+.15;message="Equipo reparado · "+quote.Cost+" oro";Push(message);return true;}
 // Attack wear and zero-bonus behavior are independently configurable; no animation or non-weapon bonuses change.
 public bool AutomaticWeaponWearActive=>RiftRepairTuning.AutomaticWearEnabled;
}
}
